text:
// Pawn Champ - Red Sea Glass. Minor quest m4, batch B (docs/quests/MINOR.md#m4-red-sea-glass).
// Mrs. Okonjo has looked for a piece of red sea glass for thirty years. A smooth customer sells
// you a "red piece" (a tumbled brake light). At lunch you can go and look on the sandbar yourself,
// and the loupe tells the real thing from the shards.
//
// Written as data: docs/STORY_DATA.md. Strict JSON inside the call. Code half: js/quests/seaglass.js.
defineStory({
  "id": "seaglass",
  "kind": "minor",
  "title": "Red Sea Glass",
  "location": "sandbar",
  "rumour": "Mrs. Okonjo has been looking for red sea glass for thirty years.",
  "endings": { "real": "The Real Thing", "brake": "Brake Light" },
  "about": [
    "Mrs. Okonjo, who keeps the library's sea glass case, has hunted red sea glass for thirty years and will pay $60 for a piece (§{okonjoWant}). You can search the sandbar at low tide yourself (§{seaglassSandbar}), where only a loupe tells real red from wet brown bottle glass. Vinnie Sloane also turns up with a convenient red piece for $25, which is really a polished brake light (§{glassSeller}).",
    "When she comes back (§{okonjoBack}) sell her whatever red piece you have. The genuine one earns her second-best jar and her gratitude (The Real Thing); the brake light embarrasses her in front of the Beachcombers (Brake Light). If you have nothing by week 3, she gives up for now."
  ],
  "cast": {
    "okonjo": {
      "name": "Adaeze Okonjo",
      "look": { "skin": "#6a4030", "hair": "#d0d0d0", "hs": 3, "coat": "#3a7a6a", "trim": "#e8c040", "style": "jacket", "long": true, "pants": "#2a2a30", "glasses": "#c8a050", "bag": "#c84a3a" }
    },
    "glassman": {
      "name": "Vinnie Sloane",
      "look": { "skin": "#f0c8a8", "hair": "#1a1a1a", "hs": 0, "coat": "#2a2a30", "trim": "#c8a050", "style": "jacket", "pants": "#3a3a48", "moustache": "#1a1a1a" }
    }
  },
  "icons": {
    "seaglass": [
      "............",
      "............",
      "....kkk.....",
      "...kRRrk....",
      "..kRRrrrk...",
      "..kRrrrrk...",
      ".krrrrrrrk..",
      "..krrrrrk...",
      "...kkrrk....",
      ".....kk.....",
      "............",
      "............"
    ],
    "glassjar": [
      "...kkkkkk...",
      "...kwwwwk...",
      "..kSSSSSSk..",
      "..kSjBgJSk..",
      "..kSGbjRSk..",
      "..kSBjgBSk..",
      "..kSjJbgSk..",
      "..kSgBjjSk..",
      "..kSJgBbSk..",
      "..kSSSSSSk..",
      "...kkkkkk...",
      "............"
    ]
  },
  "uniques": {
    "redGlass": {
      "name": "Red sea glass",
      "icon": "seaglass",
      "cat": "curio",
      "guide": 10,
      "condLabel": "Frosted",
      "wantedBy": { "name": "Adaeze Okonjo", "mult": 6 },
      "wantedKnown": "flag.glassWant",
      "tells": [
        "Frosted all over and pitted like orange peel: decades in the surf.",
        "Held to the light, it glows the deep red of old gold-ruby glass. The real thing."
      ]
    },
    "brakeGlass": {
      "name": "Red sea glass",
      "icon": "seaglass",
      "cat": "curio",
      "guide": 1,
      "condLabel": "Frosted",
      "fake": true,
      "tells": [
        "Too even. One face is ribbed like a lens.",
        "A piece of tumbled brake light. Somebody has a rock tumbler."
      ]
    },
    "glassJar": {
      "name": "Mrs. Okonjo's second-best jar",
      "icon": "glassjar",
      "cat": "curio",
      "guide": 40,
      "condLabel": "Full to the lid",
      "tells": [
        "Thirty years of Hollow Neck sea glass, sorted by color.",
        "Cobalt, seafoam, one piece of lavender. No red. That's the best jar."
      ]
    }
  },
  "scenes": {
    "okonjoWant": {
      "title": "Mrs. Okonjo is looking for red sea glass",
      "customer": "okonjo",
      "steps": [
        {
          "say": "okonjo",
          "text": [
            "Adaeze Okonjo. I keep the sea glass case at the library, and I am secretary of the Hollow Neck Beachcombers.",
            "I have been looking for red sea glass for thirty years. One piece in five thousand is red. Old car lights, old ruby glass, a lantern from a wreck.",
            "If one ever crosses your counter, I will pay $60. Any size. The sandbar at low tide is the best ground, at midday this week, but my knees don't do the sandbar any more."
          ]
        },
        { "set": { "glassWant": true } },
        { "toast": "Wanted: red sea glass, for Mrs. Okonjo ($60)", "look": "okonjo" },
        {
          "choose": [
            {
              "label": "\"I'll go and look on my lunch.\"",
              "then": [
                { "plan": "seaglass-sandbar" },
                { "say": "okonjo", "text": "Look where the pools drain. And bring something to see with. The flats lie." },
                { "toast": "Calendar: the sandbar at lunch", "look": "okonjo" }
              ]
            },
            {
              "label": "\"I'll keep an eye out.\"",
              "then": [{ "say": "okonjo", "text": "Everyone says that. Thank you anyway." }]
            }
          ]
        },
        { "leave": "okonjo" }
      ]
    },
    "glassSeller": {
      "title": "Vinnie Sloane has a red piece",
      "customer": "vinnie",
      "steps": [
        { "say": "vinnie", "text": "Heard the library lady pays good money for red glass. What d'you know, found this one this morning. Twenty-five and it's yours." },
        { "offer": { "unique": "brakeGlass" }, "as": "glass", "persona": "smooth", "asking": 25, "min": 12 },
        { "hook": "knownFake", "note": "The loupe tells you it is a fake once you look (the code half)." },
        { "leave": "vinnie" }
      ]
    },
    "seaglassSandbar": {
      "title": "Looking for red sea glass on the sandbar",
      "steps": [
        {
          "stage": "sandbar",
          "fadeOut": false,
          "actors": [{ "id": "you", "cast": "keeper", "name": "You", "at": [140, 164] }]
        },
        { "narrate": "The sandbar at low tide, at noon. Gulls, wet sand, a hundred thousand pieces of glass, and every brown beer bottle looks red when it's wet." },
        {
          "choose": [
            {
              "label": "Go through the likely pieces with your loupe",
              "hint": "(1 inspection, {hook:loupe} left)",
              "disabled": "hook.loupe < 1",
              "then": [
                { "hook": "useLoupe" },
                { "refresh": "panel" },
                { "narrate": "Brown. Brown. Amber. A car reflector. And then, under the loupe, a frosted pebble that holds the light like a coal. It's the real thing." },
                {
                  "add": {
                    "unique": "redGlass",
                    "inspected": true,
                    "clues": [
                      { "text": "Frosted all over and pitted like orange peel: decades in the surf.", "cls": "good" },
                      { "text": "Held to the light, it glows the deep red of old gold-ruby glass. The real thing.", "cls": "good" }
                    ]
                  }
                },
                { "refresh": "panel" },
                { "set": { "glassFound": true } }
              ]
            },
            {
              "label": "Pick the reddest piece by eye",
              "then": [
                { "narrate": "You pocket the reddest piece on the flats. Back in the shop, dry, it's the brown of a root beer bottle." }
              ]
            },
            {
              "label": "Just enjoy the sun for an hour",
              "then": [
                { "narrate": "You sit on the breakwater and watch the tide turn. It is, honestly, the best hour of the week." }
              ]
            }
          ]
        }
      ]
    },
    "okonjoBack": {
      "title": "Mrs. Okonjo comes back",
      "customer": "okonjo",
      "steps": [
        { "find": "red", "in": "stock", "match": { "uniqueId": ["redGlass", "brakeGlass"] }, "all": true },
        { "say": "okonjo", "text": "Mrs. Okonjo again. I don't suppose..." },
        {
          "choose": [
            {
              "label": {
                "if": "red.0.inspected && red.0.fake",
                "then": "Sell her the red sea glass (the brake light)",
                "else": { "if": "red.0.inspected", "then": "Sell her the red sea glass (the real one)", "else": "Sell her the red sea glass" }
              },
              "hint": "(+$60)",
              "if": "red.count > 0"
            },
            {
              "label": {
                "if": "red.1.inspected && red.1.fake",
                "then": "Sell her the red sea glass (the brake light)",
                "else": { "if": "red.1.inspected", "then": "Sell her the red sea glass (the real one)", "else": "Sell her the red sea glass" }
              },
              "hint": "(+$60)",
              "if": "red.count > 1",
              "note": "You might have two red pieces: one from the sandbar, one from Vinnie."
            },
            { "label": "\"Nothing yet, sorry.\"" }
          ],
          "as": "pick"
        },
        { "hook": "picked", "sets": ["it"], "note": "it: the piece you picked, or nothing." },
        {
          "if": "!it",
          "then": [
            { "say": "okonjo", "text": "Thirty years. I can wait another week.", "if": "week < 3" },
            {
              "if": "week >= 3",
              "then": [
                { "say": "okonjo", "text": "Ah well. The sea keeps the red ones for itself." },
                { "set": { "glassGaveUp": true } }
              ]
            },
            { "leave": "okonjo" },
            { "end": true }
          ]
        },
        { "sell": "it", "to": "okonjo" },
        { "refresh": "panel" },
        { "coin": 60, "why": "Sold red sea glass to Mrs. Okonjo" },
        {
          "if": "it.fake",
          "then": [
            { "set": { "glassEnd": "brake" } },
            { "say": "okonjo", "text": "Oh. Oh, it's beautiful. I shall bring it to the Beachcombers on Thursday. They will be green. Well, red." },
            { "hook": "complaint", "with": "red sea glass (a brake light, the Beachcombers say)", "note": "You sold her a fake: she comes back for her $60 in two days." }
          ],
          "else": [
            { "set": { "glassEnd": "real" } },
            { "narrate": "She holds it up to the window and turns it in the light." },
            { "say": "okonjo", "text": "Thirty years. Here: my second-best jar. It's only right. The best one has a space in it now." },
            { "if": "shelf.free", "then": [{ "add": { "unique": "glassJar" } }, { "refresh": "panel" }] },
            { "rep": 2 }
          ]
        },
        { "leave": "okonjo" }
      ]
    }
  },
  "beats": [
    { "at": "1-3", "cast": "okonjo", "scene": "okonjoWant" },
    { "at": "1-5", "cast": "glassman", "scene": "glassSeller", "if": "flag.glassWant" },
    { "at": "2-4", "cast": "okonjo", "scene": "okonjoBack", "if": "flag.glassWant && !flag.glassEnd" },
    { "at": "3-4", "cast": "okonjo", "scene": "okonjoBack", "if": "flag.glassWant && !flag.glassEnd && !flag.glassGaveUp" }
  ],
  "errands": [
    {
      "id": "seaglass-sandbar",
      "title": "Looking for red sea glass",
      "where": "the sandbar",
      "scene": "seaglassSandbar",
      "test": [{ "hook": "testLoupe", "with": 2 }]
    }
  ],
  "calendar": [
    { "id": "seaglass-sandbar", "errand": "seaglass-sandbar", "story": "seaglass", "where": "The sandbar", "title": "Red sea glass", "known": "flag.glassWant" }
  ],
  "mornings": [
    { "hook": "knownFakes", "note": "Brake lights on the shelf show as fakes once you have looked at them." }
  ],
  "epilogue": [
    { "line": "There is one red piece in the sea glass case at the library now. Mrs. Okonjo dusts it herself.", "if": "flag.glassEnd == 'real'" },
    { "line": "The Hollow Neck Beachcombers have a new rule about brake lights, and they named it after your shop.", "if": "flag.glassEnd == 'brake'" }
  ],
  "talk": {
    "by": "bettany",
    "rumour": [
      "Mrs. Okonjo comes in every morning for a roll. She's been looking for red sea glass on that beach for thirty years.",
      "Red is the rarest. She says it's out there. She says it every morning."
    ],
    "react": { "real": "Mrs. Okonjo found her red sea glass. She bought the whole tray of rolls to celebrate.", "brake": "Mrs. Okonjo's red sea glass was a brake light. She's still looking. She says it was a good practice run." },
    "sway": { "real": { "bettany": 2 } }
  },
  "outcome": "flag.glassEnd"
});
